head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setCellInputType]<br/>inputType='custom' 인 Column 의 특정 Body Cell 에 inputType 속성을 설정합니다.",
    "validation" : [
        "info(필수) 파라미터로 변경할 inputType 속성값을 포함한 연관 속성값을 JSON 형식의 객체로 설정할 수 있어야 합니다.",
        "info.inputType(필수) 파라미터로 Cell 에 설정할 inputType 속성값을 설정할 수 있어야 합니다.",
        "info.inputType 파라미터에 'drilldown' 설정 시 메소드가 실행되지 않습니다.",
        "info.inputType 파라미터에 'custom' 설정 시 'text' 로 처리됩니다.",
        "info.inputType 파라미터에 지원하는 inputType 속성값 이외의 값을 설정 시 'text' 로 처리됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof dlt_item !== 'undefined') {
        $p.data.remove("dlt_item");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] col1~col3 은 inputType=custom + setCellInputTypeCustom=true (typeGetter 미설정), 컬럼 id 는 DataList 컬럼과 일치해 편집 가능. rowIndex/columnInfo 는 0,0 고정.\n[절차] info.inputType 선택 후 setCellInputType 실행. select/checkcombobox/autoComplete 선택 시 info.itemSet(dlt_item) 으로 아이템 바인딩.\n[확인] 셀(0,0) 을 더블클릭(편집모드 진입)하면 셀 하위에 렌더된 태그와 type 속성을 리턴창에 출력합니다.\n[참고] drilldown=메소드 미실행(불변). custom/미지원값은 가이드상 text 처리이나 엔진은 원값 유지."', '', 'label1');

    let strNameSpace = $c.gcm.getNameSpace();

    // itemSet 바인딩용 DataList (select/checkcombobox/autoComplete inputType 용)
    //  ※ createBasicDataList 는 col1~col4 스키마만 생성하므로 itemSet label/value 도 col1/col2 사용 (col1=라벨, col2=값)
    $c.gcm.createBasicDataList('', '', 'dlt_item');
    dlt_item.setJSON([
        { "col1": "서울", "col2": "01" },
        { "col1": "부산", "col2": "02" },
        { "col1": "대구", "col2": "03" }
    ]);

    // 본문 DataList (custom 셀 편집용, 초기값 빈값) - createBasicDataList 는 col1~col4 컬럼
    $c.gcm.createBasicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { "col1": "", "col2": "", "col3": "" },
        { "col1": "", "col2": "", "col3": "" },
        { "col1": "", "col2": "", "col3": "" },
        { "col1": "", "col2": "", "col3": "" }
    ]);

    // target 생성
    //  - setCellInputTypeCustom="true" : custom 컬럼의 Cell 단위 inputType 변경 허용
    //  - Body 컬럼 id 는 DataList 컬럼(col1~col3) 과 일치해야 편집 가능(불일치 시 자동 readOnly)
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" setCellInputTypeCustom="true" dataList="data:dlt_bind" ev:oncelldblclick="scwin.target1_oncelldblclick" id="" style="width:560px;height:200px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="180" inputType="text" id="hcol1" value="col1 (custom)"></w2:column>';
    strTarget += '<w2:column width="180" inputType="text" id="hcol2" value="col2 (custom)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol3" value="col3 (custom)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="180" inputType="custom" displayMode="label" value="" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="180" inputType="custom" displayMode="label" value="" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="*" inputType="custom" displayMode="label" value="" id="col3" dataList="col3"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// 셀 더블클릭(편집모드 진입) 시, 셀 하위에 렌더된 입력 요소의 태그와 type 속성을 출력한다.
//  - inputType 별로 편집 렌더 요소가 다르다 (text->input type=text, textarea->textarea,
//    checkbox->input type=checkbox, select/checkcombobox/autoComplete->[role=combobox] 등)
//  - 동적 입력 요소는 절대위치라 td 자식이 아니라 document 에 생성됨(id: ..._dynamic_<type>_R_C) -> id 로 조회
scwin.target1_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    setTimeout(function () {
        // 편집모드로 렌더된 동적 입력 요소(절대위치, id: ..._dynamic_<type>_R_C)
        let el = document.querySelector('[id*="_dynamic_"][id$="_' + rowIndex + '_' + columnIndex + '"]');
        if (el) {
            let typeAttr = el.getAttribute('type');
            let role = el.getAttribute('role');
            let cls = el.className || "";
            wf_body_bottom.getObj("scwin").setReturnValue(
                "셀(" + rowIndex + ", " + columnIndex + ") 더블클릭 -> [편집모드] 렌더 태그 : <" + el.tagName.toLowerCase()
                + (typeAttr ? ' type="' + typeAttr + '"' : '')
                + (role ? ' role="' + role + '"' : '')
                + (cls ? ' class="' + cls + '"' : '') + ">");
            return;
        }
        // 동적 편집요소가 없으면, td 내부에 항상 표시되는 입력요소(checkbox 등) 를 우선 조회 -> 태그 + type 출력
        let td = document.getElementById('mf_target1_cell_' + rowIndex + '_' + columnIndex);
        let inner = td ? td.querySelector('input, textarea, select, [role=combobox]') : null;
        if (inner) {
            let t = inner.getAttribute('type');
            let r = inner.getAttribute('role');
            let c = inner.className || "";
            wf_body_bottom.getObj("scwin").setReturnValue(
                "셀(" + rowIndex + ", " + columnIndex + ") 더블클릭 -> 렌더 태그 : <" + inner.tagName.toLowerCase()
                + (t ? ' type="' + t + '"' : '')
                + (r ? ' role="' + r + '"' : '')
                + (c ? ' class="' + c + '"' : '') + ">");
            return;
        }
        // 입력요소가 없으면(custom/미지원값 등 text 미처리로 편집 불가) 셀의 표시(display) 태그 출력
        let child = td ? td.firstElementChild : null;
        let dispTag = child
            ? ("<" + child.tagName.toLowerCase() + (child.className ? ' class="' + child.className + '"' : '') + ">")
            : "(없음)";
        wf_body_bottom.getObj("scwin").setReturnValue(
            "셀(" + rowIndex + ", " + columnIndex + ") 더블클릭 -> [편집모드 미진입] 표시 태그 : " + dispTag);
    }, 150);
};



scwin.btn_setCellInputType_onclick = function () {
    // rowIndex / columnInfo 는 0, 0 고정 (이 샘플은 info.inputType 검증 전용)
    let rowIndex = 0;
    let columnInfo = 0;
    let inputType = par_inputType.getValue();

    // info 객체 구성 : info.inputType (ItemSet 기반 타입은 itemSet 함께 전달, col1=라벨/col2=값)
    let info = { inputType: inputType };
    if (inputType === "select" || inputType === "checkcombobox" || inputType === "autoComplete") {
        info.itemSet = { nodeset: "data:dlt_item", label: "col1", value: "col2" };
    }

    // 메소드 실행
    scwin.target1.setCellInputType(rowIndex, columnInfo, info);
    try { scwin.target1.refreshCell(rowIndex, columnInfo); } catch (e) {}

    // 실제 셀에 반영된 inputType(원값) / 렌더타입 조회
    let api = scwin.target1;
    let ci = api.getCellInfo(api.getColumnIndex(columnInfo));
    let cm = ci.cellManagerHashByRowIndex ? ci.cellManagerHashByRowIndex[api.dataList.getRealRowIndex(rowIndex)] : null;
    let actualType = cm ? cm.options.inputType : "?";
    let renderType = cm ? cm.initializeInputType : "?";

    let note = "";
    if (inputType === "drilldown") {
        note = " | drilldown -> 메소드 미실행(불변)";
    } else if (inputType === "custom" || inputType === "unsupportedType") {
        // 가이드는 'text' 처리라고 하나, 엔진은 원값을 유지하여 text 처럼 동작하지 않음(편집모드 미진입) - 결함
        note = " | ※ 가이드: 'text' 처리 / 실제: 원값('" + actualType + "') 유지 -> text 미처리(편집모드 미진입, 가이드 불일치)";
    }

    wf_body_bottom.getObj("scwin").setReturnValue("셀(0,0) 더블클릭 시 편집 렌더 태그/type 출력 (text 는 input 편집, custom/미지원은 편집모드 미진입)");
}
